sp_widget.css:
.home-banner {
  background-color: #004080;
  color: white;
  text-align: center;
  padding: 40px;
  border-radius: 10px;
  margin-bottom: 20px;
}

.banner-buttons {
  margin-top: 20px;
}

.banner-buttons .btn {
  margin: 10px;
  font-size: 18px;
  padding: 12px 24px;
  border-radius: 5px;
}

.btn-primary {
  background-color: #ffcc00;
  color: #004080;
}

.btn-secondary {
  background-color: white;
  color: #004080;
  border: 2px solid #ffcc00;
}

.btn:hover {
  opacity: 0.8;
}
